async function loadCloud(quiet=false) {
  if (!isCloud()) { cloud = { connected:false,projects:[],linked:[],creators:[],user:null,notifications:[],error:'' }; render(); return; }
  try {
    const payload = await api('/bootstrap');
    cloud = { connected:true,projects:payload.projects||[],linked:[],creators:payload.creators||[],user:payload.user,notifications:payload.notifications||[],error:'' };
    state.liked = payload.liked||[]; state.saved = payload.saved||[]; state.following = payload.following||[];
    state.boards = payload.boards||[]; state.comments = payload.comments||{}; state.updates = payload.updates||{};
    state.mine = payload.myProjects || cloud.projects.filter(p=>p.creatorId===cloud.user?.id);
    if (cloud.user) state.user = { ...state.user, ...cloud.user };
    render();
  } catch(err) { cloud.connected = false; cloud.error=err.message; if (!quiet) toast(`API connection failed: ${err.message}`,true); render(); }
}
