function titleForPage() { return ({ discover: 'Discover', explore: 'Explore', bookmarks: 'Saved projects', boards: 'Collections', studio: 'Creator studio', following: 'Following', leaderboard: 'Leaderboard', 'my-projects': 'My projects', profile: 'Profile', settings: 'Settings', download: 'Windows download' })[state.page] || 'Discover'; }
function projectThumb(p) { const cover = validUrl(p.cover); const glyph = ({ orbit: 'grid', neural: 'sparkles', pixel: 'gamepad', luau: 'code', motion: 'sparkles', terminal: 'terminal', atlas: 'globe', canvas: 'edit', garden: 'grid', skyward: 'gamepad', nexus: 'box', color: 'sparkles', custom: 'code' })[p.theme] || 'code'; return `<div class="project-thumb ${safeText(p.theme || 'custom')}">${cover ? `<img class="custom-cover" src="${safeText(cover)}" alt="" loading="lazy" referrerpolicy="no-referrer"/>` : ''}<div class="thumb-overlay"></div><span class="thumb-badge">${safeText(p.category)}</span>${p.visibility&&p.visibility!=='public'?`<span class="visibility-badge">${safeText(p.visibility)}</span>`:''}${p.featured ? '<span class="thumb-featured">✦ Featured</span>' : ''}<div class="thumb-center">${icon(glyph)}<span>${safeText(p.title)}</span></div></div>`; }
function projectCard(p) {
  const author = getCreator(p.creatorId);
  const liked = state.liked.includes(p.id);
  const saved = state.saved.includes(p.id);
  return `<article class="project-card"><button class="card-cover" data-action="open" data-id="${p.id}" aria-label="View ${safeText(p.title)}" style="display:block;width:100%;padding:0;border:0;background:none;text-align:inherit">${projectThumb(p)}</button><div class="card-body"><div class="card-title-row"><h3 class="card-title" data-action="open" data-id="${p.id}" role="button" tabindex="0">${safeText(p.title)}</h3><button class="reaction bookmarked ${saved ? 'active' : ''}" title="${saved ? 'Remove bookmark' : 'Bookmark'}" aria-label="Bookmark ${safeText(p.title)}" data-action="save" data-id="${p.id}">${icon('bookmark')}</button></div><p class="card-summary">${safeText(p.tagline)}</p><div class="tags">${p.tags.slice(0, 3).map((t) => `<span class="tag">${safeText(t)}</span>`).join('')}</div><div class="card-footer"><button class="author" data-action="profile" data-id="${p.creatorId}">${avatar(author)}<span><span class="author-name" style="display:block">${safeText(author.name)}</span><span class="author-info">${p.daysAgo ? `${p.daysAgo}d ago` : 'Just now'}</span></span></button><div class="reactions"><button class="reaction ${liked ? 'active' : ''}" title="Like project" data-action="like" data-id="${p.id}">${icon('heart')} ${fmt(p.likes + (liked ? 1 : 0))}</button><button class="reaction" data-action="open" data-id="${p.id}" title="View comments">${icon('message')} ${fmt(p.comments + (state.comments[p.id] || []).length)}</button></div></div></div></article>`;
}
function results(filter) {
  let projects = allProjects();
  if (filter !== 'my-projects' && filter !== 'bookmarks') projects = projects.filter(p=>p.visibility==='public' || (!p.visibility && !isCloud()));
  if (filter === 'bookmarks') projects = projects.filter((p) => state.saved.includes(p.id));
  if (filter === 'following') projects = projects.filter((p) => state.following.includes(p.creatorId));
  if (filter === 'my-projects') projects = projects.filter(isMine);
  if (state.category !== 'All projects' && (filter === 'discover' || filter === 'explore')) projects = projects.filter((p) => p.category === state.category);
  const query = state.search.trim().toLowerCase();
  if (query) projects = projects.filter((p) => [p.title, p.tagline, p.description, p.category, ...p.tags, getCreator(p.creatorId).name].join(' ').toLowerCase().includes(query));
  return projects.sort((a, b) => state.sort === 'latest' ? a.daysAgo - b.daysAgo : state.sort === 'liked' ? (b.likes + Number(state.liked.includes(b.id))) - (a.likes + Number(state.liked.includes(a.id))) : ((b.likes + Number(state.liked.includes(b.id))) * 2 + b.views / 90) - ((a.likes + Number(state.liked.includes(a.id))) * 2 + a.views / 90));
}
const empty = (glyph, title, message, label = 'Explore projects', action = 'explore') => `<div class="blank-state">${icon(glyph)}<h3>${title}</h3><p>${message}</p><button class="btn primary" data-action="${action}">${label} ${icon('arrow', 'tiny-icon')}</button></div>`;
function grid(projects, emptyTitle = 'No projects found', message = 'Try another search or change your filters.') { return projects.length ? `<div class="grid-projects">${projects.map(projectCard).join('')}</div>` : empty('search', emptyTitle, message, 'Explore projects', 'explore'); }
const filterChips = () => `<div class="filters" role="group" aria-label="Project categories">${categories.map((cat) => `<button class="chip ${state.category === cat.name ? 'active' : ''}" data-action="category" data-category="${safeText(cat.name)}">${icon(cat.icon)}${safeText(cat.name)}</button>`).join('')}</div>`;
const sortBar = (title = 'Made by the community') => `<div class="tools-row"><h3>${safeText(title)} <span class="muted" style="font-size:12px;font-family:'DM Sans'">(${results(state.page).length})</span></h3><label><span class="sr-only">Sort projects</span><select id="sort-select"><option value="trending" ${state.sort === 'trending' ? 'selected' : ''}>Trending</option><option value="latest" ${state.sort === 'latest' ? 'selected' : ''}>Newest</option><option value="liked" ${state.sort === 'liked' ? 'selected' : ''}>Most liked</option></select></label></div>`;
function demoHomePage() { const featured = seedProjects.find((p) => p.featured) || seedProjects[0]; return `<div class="announcement"><span class="announcement-pill">NEW · v1.5</span> A better home for builders <span class="announcement-sep">·</span> Discover, collect, launch & grow <button class="announcement-link" data-action="nav" data-page="studio">Open Studio ${icon('arrow', 'tiny-icon')}</button></div><div class="hero upgraded-hero"><div class="hero-content"><p class="eyebrow" style="color:#b4ffa6;margin:0 0 12px">THE CREATIVE CORNER OF THE INTERNET <span class="eyebrow-star">✳</span></p><h1>Build something.<br/><span>Show the world.</span></h1><p>A place for side projects, ambitious ideas, and everything in between. Discover makers and give your work the spotlight it deserves.</p><div class="hero-actions"><button class="btn primary" data-action="new">${icon('plus','tiny-icon')} Share a project</button><button class="btn secondary" data-action="nav" data-page="explore">Explore projects ${icon('arrow','tiny-icon')}</button></div><div class="hero-sub"><span class="pulse-light"></span> Your next favorite project is one click away <span class="hero-demo">· Demo community</span></div></div><div class="hero-decoration hero-terminal" aria-hidden="true"><div class="terminal-head"><span class="terminal-circles">● ● ●</span><span>~/devshow/launch.ts</span><span>↗</span></div><div class="terminal-body"><span class="line-no">01</span> <span class="t-purple">const</span> idea <span class="t-white">=</span> <span class="t-yellow">'something amazing'</span>;<br/><span class="line-no">02</span> <span class="t-purple">const</span> community <span class="t-white">=</span> <span class="t-cyan">'everyone'</span>;<br/><span class="line-no">03</span> <span class="t-purple">await</span> <span class="t-green">build</span>(idea);<br/><span class="line-no">04</span> <span class="t-green">launch</span>({ audience: community });<br/><span class="line-no">05</span> <span class="terminal-cursor">▌</span><div class="terminal-result"><span class="pulse-light"></span> ✦ Your project is ready to shine</div></div></div></div>
  <div class="stats-strip"><div class="stat"><span class="stat-icon">${icon('grid')}</span><span><strong>${fmt(allProjects().length)}</strong><small>Showcase projects*</small></span></div><div class="stat"><span class="stat-icon">${icon('users')}</span><span><strong>${fmt(creators.length + 1)}</strong><small>Creators in preview*</small></span></div><div class="stat"><span class="stat-icon">${icon('heart')}</span><span><strong>${fmt(allProjects().reduce((n,p) => n + p.likes, 0) + state.liked.length)}</strong><small>Demo reactions*</small></span></div></div>
  <div class="featured-layout"><div class="featured-copy"><p class="eyebrow">✳ EDITOR'S PICK · EXAMPLE PROJECT</p><h2>Ideas worth exploring.</h2><p>Beautiful work starts with someone sharing a first version. Check out this featured example project.</p><button class="btn secondary small" data-action="open" data-id="${featured.id}">View project ${icon('arrow','tiny-icon')}</button></div><button class="featured-art" data-action="open" data-id="${featured.id}"><span class="featured-art-badge">PROJECT SPOTLIGHT</span>${projectThumb(featured)}<span class="featured-art-title">${safeText(featured.title)} <span>↗</span></span></button></div>
  <div class="section-head"><div><p class="eyebrow">CURATED FOR THE CURIOUS</p><h2>Projects to get lost in <span class="heading-sparkle">✳</span></h2><p>From first prototypes to polished products.</p></div><button class="text-link" data-action="nav" data-page="explore">View everything ${icon('arrow','tiny-icon')}</button></div>${filterChips()}${sortBar('Explore the gallery')}${grid(results('discover'))}<p class="more-indicator">*Illustrative preview content · Your work is saved privately in your browser</p>`; }
function explorePage() { return `<p class="eyebrow">YOUR NEXT INSPIRATION</p><h1 class="page-title">Explore projects</h1><p class="page-lead">Browse public projects and open-source repositories, and find developers to collaborate with.</p>${filterChips()}${sortBar('All projects')}${grid(results('explore'))}<p class="more-indicator">${online()?'Public projects from the DevShow server':'Example projects · Connect a server to see the community feed'}</p>`; }
function collectionPage(which) { const config = { bookmarks: ['Your bookmarks', 'Keep track of inspiring work. Tap the bookmark icon on any project to save it.', 'Nothing saved yet', 'Bookmark a project to find it again here.'], following: ['Following feed', 'Projects from creators you follow will appear here.', 'Not following anyone yet', 'Open a creator profile and select Follow.'], 'my-projects': ['My projects', 'All your published showcases in one place.', 'You haven\'t shared a project', 'Publish something you built and it will appear here.'] }[which]; return `<p class="eyebrow">YOUR SPACE</p><div class="section-head"><div><h1 class="page-title">${config[0]}</h1><p class="page-lead">${config[1]}</p></div>${which === 'my-projects' ? `<button class="btn primary small" data-action="new">${icon('plus', 'tiny-icon')} New project</button>` : ''}</div>${results(which).length ? grid(results(which)) : empty(which === 'bookmarks' ? 'bookmark' : which === 'following' ? 'users' : 'folder', config[2], config[3], which === 'my-projects' ? 'Publish project' : 'Explore projects', which === 'my-projects' ? 'new' : 'explore')}`; }
function ranking() { return (isCloud() ? cloud.creators : [...creators, getCreator('self')]).map((c) => ({ ...c, score: allProjects().filter((p) => p.creatorId === c.id || (c.id === 'self' && isMine(p))).reduce((sum, p) => sum + p.likes + Number(state.liked.includes(p.id)) + p.comments * 3, 0) })).sort((a,b) => b.score - a.score); }
function leaderboardPage() { return `<p class="eyebrow">COMMUNITY SPOTLIGHT</p><h1 class="page-title">The leaderboard</h1><p class="page-lead">Meet the makers behind the projects. Rankings are based on project engagement.</p><div class="leader-table">${ranking().map((c,i) => `<button class="leader-large" data-action="profile" data-id="${c.id}" style="text-align:left;cursor:pointer"><span class="leader-rank">${String(i+1).padStart(2,'0')}</span>${avatar(c, 'medium')}<span class="leader-info"><strong>${safeText(c.name)}</strong><small>@${safeText(c.handle)} · ${safeText(c.role)}</small></span><span class="leader-points">${fmt(c.score)} pts</span>${icon('chevron','tiny-icon')}</button>`).join('')}</div>`; }
function boardsPage() { const selected = state.boards.find((b) => b.id === boardId); if (selected) { const projects = allProjects().filter((p) => selected.projects.includes(p.id)); return `<div class="backline"><button class="btn secondary small" data-action="back-boards">← All collections</button><button class="btn secondary small" data-action="delete-board" data-id="${safeText(selected.id)}">${icon('trash','tiny-icon')} Delete collection</button></div><div class="collection-cover"><span class="collection-glyph">${icon('layers')}</span><p class="eyebrow">PERSONAL COLLECTION</p><h1 class="page-title">${safeText(selected.name)}</h1><p>${safeText(selected.description || 'A little corner of inspiration.')}</p><span class="collection-total">${projects.length} saved project${projects.length === 1 ? '' : 's'}</span></div>${projects.length ? grid(projects) : empty('bookmark','This collection is empty','Open a project and choose Add to collection to save it here.')}`; } return `<div class="section-head page-heading"><div><p class="eyebrow">YOUR CREATIVE LIBRARY</p><h1 class="page-title">Collections</h1><p class="page-lead">Organize the projects that inspire you into personal collections.</p></div><button class="btn primary small" data-action="create-board">${icon('plus','tiny-icon')} Create collection</button></div><div class="collection-grid"><button class="collection-card create-collection" data-action="create-board"><span class="collection-card-icon">${icon('plus')}</span><strong>New collection</strong><small>Start collecting inspiration</small></button>${state.boards.map((b,i) => `<button class="collection-card collection-card-${i%4}" data-action="board-open" data-id="${safeText(b.id)}"><span class="collection-card-icon">${icon('layers')}</span><strong>${safeText(b.name)}</strong><small>${b.projects.length} saved · ${safeText(b.description || 'Your curated finds')}</small><span class="collection-chevron">↗</span></button>`).join('')}</div>${!state.boards.length ? '<p class="subtle" style="margin-top:20px">Create a collection, then add projects from any project detail page.</p>' : ''}`; }
function studioPage() { const comments = Object.values(state.comments).reduce((n, c) => n + (Array.isArray(c) ? c.length : 0), 0); const entries = Object.values(state.updates).reduce((n, x) => n + (Array.isArray(x) ? x.length : 0), 0); return `<div class="studio-head"><div><p class="eyebrow">THE MAKER WORKSPACE</p><h1 class="page-title">Creator studio <span class="heading-sparkle">✳</span></h1><p class="page-lead">Your projects, progress, and ideas — all in one place. Connect a server for data synced across your devices.</p></div><button class="btn primary" data-action="new">${icon('plus','tiny-icon')} New project</button></div><div class="studio-hero"><div><span class="studio-overline">YOUR SPACE TO CREATE</span><h2>Make something people remember.</h2><p>Start with a project, tell its story, and keep people in the loop with build updates.</p><button class="btn secondary small" data-action="import">${icon('github','tiny-icon')} Import from GitHub</button></div><div class="studio-graphic" aria-hidden="true"><span>{ build }</span><i>↗</i></div></div><div class="studio-metrics"><div class="studio-metric"><span>${icon('folder')}</span><strong>${state.mine.length}</strong><small>Your published projects</small></div><div class="studio-metric"><span>${icon('calendar')}</span><strong>${entries}</strong><small>Build updates</small></div><div class="studio-metric"><span>${icon('bookmark')}</span><strong>${state.saved.length}</strong><small>Saved projects</small></div><div class="studio-metric"><span>${icon('message')}</span><strong>${comments}</strong><small>Local comments</small></div></div><div class="studio-section"><div class="section-head"><div><h2>Manage your work</h2><p>Edit projects and publish updates.</p></div><button class="text-link" data-action="nav" data-page="my-projects">See all ${icon('arrow','tiny-icon')}</button></div>${state.mine.length ? `<div class="studio-project-list">${state.mine.map((p) => `<div class="studio-project-row">${projectThumb(p)}<div class="studio-project-meta"><strong>${safeText(p.title)}</strong><span>${safeText(p.category)} · ${(state.updates[p.id] || []).length} updates</span></div><div class="studio-project-actions"><button class="btn secondary small" data-action="edit" data-id="${safeText(p.id)}">${icon('edit','tiny-icon')} Edit</button><button class="btn secondary small" data-action="update" data-id="${safeText(p.id)}">${icon('plus','tiny-icon')} Update</button></div></div>`).join('')}</div>` : empty('rocket', 'Your next launch starts here', 'Import a public repository or create a new project to get started.', 'Create project', 'new')}</div><div class="studio-tip"><span>${icon('info')}</span><div><strong>Ready to go live?</strong><p>Use DevShow Desktop for private PC storage, or connect a public HTTPS Node.js API to share your work across devices.</p></div></div>`; }
function profilePage() { const creator = getCreator(profileId); const isSelf = creator.id === 'self'; const creatorProjects = allProjects().filter((p) => isSelf ? isMine(p) : p.creatorId === creator.id); const followed = state.following.includes(creator.id); return `<div class="panel" style="padding:0;overflow:hidden"><div class="profile-banner"></div><div class="profile-info">${avatar(creator, 'large')}<div class="profile-actions">${isSelf ? `<button class="btn secondary small" data-action="edit-profile">${icon('edit','tiny-icon')} Edit profile</button>` : `<button class="btn ${followed ? 'secondary' : 'primary'} small" data-action="follow" data-id="${creator.id}">${icon(followed ? 'check' : 'plus','tiny-icon')} ${followed ? 'Following' : 'Follow creator'}</button>`}</div><h2>${safeText(creator.name)}</h2><p>@${safeText(creator.handle)} · ${safeText(creator.role)}</p><p style="margin-top:12px">${safeText(creator.bio || (isSelf ? state.user.bio : 'Building projects and sharing the process.'))}</p>${creator.location?`<p class="profile-location">${icon('globe','tiny-icon')} ${safeText(creator.location)}</p>`:''}${Array.isArray(creator.skills)&&creator.skills.length?`<div class="tags">${creator.skills.slice(0,10).map(t=>`<span class="tag">${safeText(t)}</span>`).join('')}</div>`:''}${(validUrl(creator.github) || validUrl(creator.website)) ? `<div class="profile-links">${validUrl(creator.github) ? `<a href="${safeText(validUrl(creator.github))}" target="_blank" rel="noopener noreferrer">${icon('github','tiny-icon')} GitHub ↗</a>` : ""}${validUrl(creator.website) ? `<a href="${safeText(validUrl(creator.website))}" target="_blank" rel="noopener noreferrer">${icon('globe','tiny-icon')} Website ↗</a>` : ""}</div>` : ""}<div class="profile-stats"><span><b>${creatorProjects.length}</b> Projects</span><span><b>${fmt(creator.followers + (followed ? 1 : 0))}</b> Followers</span><span><b>${fmt(creatorProjects.reduce((v,p)=>v+p.likes,0))}</b> Likes</span></div></div></div>${creator.pinnedProjectId && creatorProjects.some(p=>p.id===creator.pinnedProjectId) ? `<section class="pinned-project"><p class="eyebrow">PINNED SHOWCASE</p>${projectCard(creatorProjects.find(p=>p.id===creator.pinnedProjectId))}</section>` : ''}<div class="profile-projects"><div class="section-head"><h2>${isSelf ? 'My' : `${safeText(creator.name.split(' ')[0])}\'s`} projects</h2></div>${creatorProjects.length ? grid(creatorProjects) : empty('folder','No projects here yet','Share your first project with the community.','Publish project','new')}</div>`; }
function demoSettingsPage() { return `<p class="eyebrow">YOUR PREFERENCES</p><h1 class="page-title">Settings</h1><p class="page-lead">Customize your local preview experience.</p><div class="panel"><div class="setting-row"><div><h3>Appearance</h3><p>Choose a theme for DevShow.</p></div><button class="btn secondary small" data-action="theme">${icon(state.theme === 'dark' ? 'sun' : 'moon','tiny-icon')} ${state.theme === 'dark' ? 'Light mode' : 'Dark mode'}</button></div><div class="setting-row"><div><h3>Edit demo profile</h3><p>Update your display name, handle, and bio.</p></div><button class="btn secondary small" data-action="edit-profile">Edit ${icon('chevron','tiny-icon')}</button></div><div class="setting-row"><div><h3>Export your data</h3><p>Download a JSON backup with projects, collections, build logs, likes, bookmarks, and profile.</p></div><button class="btn secondary small" data-action="export">${icon('download','tiny-icon')} Export backup</button></div><div class="setting-row"><div><h3>Restore a backup</h3><p>Import a DevShow JSON backup from this or another device.</p></div><button class="btn secondary small" data-action="restore">${icon('upload','tiny-icon')} Import JSON</button><input type="file" id="backup-file" accept="application/json,.json" hidden/></div><div class="setting-row"><div><h3>Keyboard shortcuts</h3><p>Search quickly and navigate the site using your keyboard.</p></div><button class="btn secondary small" data-action="shortcuts">${icon('keyboard','tiny-icon')} View</button></div><div class="setting-row"><div><h3>Reset demo data</h3><p>Remove your likes, bookmarks, projects, comments, follows and profile changes stored on this device.</p></div><button class="btn secondary small" data-action="reset">Reset ${icon('refresh','tiny-icon')}</button></div></div><div class="notice warning"><b>Local demo mode.</b> This build doesn't authenticate users or sync data across browsers. Real accounts and shared community actions require the separate API described in the included architecture documentation.</div>`; }

function homePage() {
  if (!isCloud()) return demoHomePage();
  const list=results('discover');
  return `<div class="announcement"><span class="announcement-pill">DEVSHOW · v2.2</span> ${online() ? 'Connected to DevShow Node.js API' : 'Connect a Node.js server to see community projects'} <button class="announcement-link" data-action="nav" data-page="settings">${online()?'Server settings':'Connect server'} →</button></div>
  <div class="hero upgraded-hero"><div class="hero-content"><p class="eyebrow">THE CREATOR NETWORK</p><h1>Build something.<br><span>Show the world.</span></h1><p>Share projects, publish build logs, discover other developers, and grow your portfolio.</p><div class="hero-actions"><button class="btn primary" data-action="new">${icon('plus','tiny-icon')} Publish a project</button><button class="btn secondary" data-action="explore">Explore projects</button></div></div><div class="hero-decoration"><div class="code-window"><div class="code-top"><i></i><i></i><i></i></div><div class="code-line"></div><div class="code-line"></div><div class="code-line"></div></div></div></div>
  ${!online()?`<div class="notice"><b>API not connected.</b> ${safeText(cloud.error||'Add your Node server URL in Settings to load shared accounts and projects.')}</div>`:`<div class="stats-strip"><div class="stat"><span class="stat-icon">${icon('folder')}</span><span><strong>${fmt(cloud.projects.length)}</strong><small>Published projects</small></span></div><div class="stat"><span class="stat-icon">${icon('users')}</span><span><strong>${fmt(cloud.creators.length)}</strong><small>Developers</small></span></div><div class="stat"><span class="stat-icon">${icon('heart')}</span><span><strong>${fmt(cloud.projects.reduce((n,p)=>n+p.likes,0))}</strong><small>Project likes</small></span></div></div>`}
  <div class="section-head"><div><h2>Explore the community</h2><p>Work shared by actual DevShow accounts</p></div><button class="link" data-action="explore">See all →</button></div>${filterChips()}${grid(list)}
  `;
}
function renderAside() {
  if (!isCloud()) return demoRenderAside();
  return `<div class="aside-card"><div class="aside-head"><h3>Connection status</h3>${icon('globe')}</div><p class="subtle">${online() ? `Connected · ${cloud.creators.length} registered developers` : 'Offline · Configure API in Settings'}</p><button style="margin-top:12px" class="btn secondary small" data-action="nav" data-page="settings">API settings ${icon('chevron','tiny-icon')}</button></div><div class="aside-card"><div class="aside-head"><h3>Top developers</h3>${icon('trophy')}</div>${ranking().slice(0,5).map((c,i)=>`<button class="leader" style="width:100%;border:0;background:none;text-align:left;color:var(--text)" data-action="profile" data-id="${safeText(c.id)}"><span class="leader-rank">${i+1}</span>${avatar(c)}<span class="leader-info"><strong>${safeText(c.name)}</strong><small>@${safeText(c.handle)}</small></span><span class="leader-points">${fmt(c.score)}</span></button>`).join('')||'<p class="subtle">No developers yet.</p>'}</div>`;
}
function downloadPage() {
  const ready=windowsDownload.ready;
  const bytes=windowsDownload.size?`${(windowsDownload.size/1048576).toFixed(1)} MB · `:'';
  const url=safeText(windowsDownload.url);
  return `<p class="eyebrow">DEVSHOW COMPANION · WINDOWS</p><h1 class="page-title">Your work. Saved on your PC.</h1><p class="page-lead">DevShow Desktop is a single Windows executable. Open it to launch your own private DevShow workspace with a local Node.js API and SQLite saving. No ZIP and no Node.js install required.</p>
  <section class="desktop-card"><div class="desktop-card-head"><span class="desktop-mark">${icon('terminal')}</span><div><span class="desktop-overline">WINDOWS 10/11 · 64-BIT</span><h2>DevShow Desktop <span>v2.1</span></h2><p>Local accounts, projects, Creator Studio and profile manager — ready to save offline.</p></div></div>
  <div class="desktop-actions"><a class="btn primary desktop-download" href="${url}" rel="noopener noreferrer" target="_blank" ${ready?'download':''}>${icon('download','tiny-icon')} ${ready?'Download DevShow-Desktop.exe':'View releases / build status'}</a><span class="download-status">${ready?`Verified release · ${bytes}${safeText(windowsDownload.version)}`:'Direct .exe becomes available after the Windows release build completes.'}</span></div>
  </section><div class="desktop-benefits"><div class="panel"><h3>${icon('database')} Persistent saving</h3><p>Your local database lives under Windows AppData, not inside a browser tab. Future app upgrades keep your records.</p></div><div class="panel"><h3>${icon('user')} Profile manager</h3><p>Create a local account, edit your profile, publish projects, manage collections and updates.</p></div><div class="panel"><h3>${icon('globe')} Local vs online</h3><p>Desktop saves on that PC only. To share with the world, connect the GitHub Pages site to a separately hosted HTTPS Node server.</p></div></div>
  <div class="panel desktop-guide"><h3>How it works</h3><p>1. Download the .exe on a Windows computer. 2. Run it; your browser opens DevShow at <code>http://127.0.0.1:3217</code>. 3. Register a local account and start publishing. Keep the app open while using that address.</p><p class="notice">The app is not code-signed yet, so Windows may show a publisher warning. Review the open-source code and release details before running it. Do not bypass security protections for untrusted files.</p><p>Need online profiles shared with everyone? A public HTTPS-hosted Node.js server and persistent storage are still required.</p></div>`;
}
async function checkWindowsRelease() {
  try {
    const response=await fetch('https://api.github.com/repos/SillyDev2026/DevShow.io/releases/latest',{headers:{Accept:'application/vnd.github+json'}});
    if(!response.ok) return;
    const release=await response.json();
    const asset=(release.assets||[]).find(a=>a.name==='DevShow-Desktop.exe'&&a.state==='uploaded');
    if(!asset) return;
    windowsDownload={url:asset.browser_download_url,ready:true,version:release.tag_name||'',size:asset.size||0};
    if(state.page==='download') refreshContent();
  }catch{}
}
function settingsPage() {
  const connection = `<div class="panel" style="margin-bottom:20px"><p class="eyebrow">DEVSHOW CLOUD</p><h2>Node.js server & profile manager</h2><p class="subtle" style="margin:12px 0">${online()?`Connected to ${safeText(apiBase())}`:isCloud()?`Trying ${safeText(apiBase())}. ${safeText(cloud.error||'')}`:'Demo mode — add your public Node.js API URL to sync across devices.'}</p><div class="hero-actions"><button class="btn primary small" data-action="server">${icon('globe','tiny-icon')} ${isCloud()?'Change server':'Connect server'}</button>${isCloud()?`<button class="btn secondary small" data-action="sync">${icon('refresh','tiny-icon')} Refresh</button>`:''}<button class="btn secondary small" data-action="auth">${icon('user','tiny-icon')} ${signedIn()?'Account manager':'Sign in / Register'}</button>${getToken()?`<button class="btn secondary small" data-action="logout">Sign out</button>`:''}</div></div>`;
  return `<p class="eyebrow">PREFERENCES & ACCOUNT</p><h1 class="page-title">Settings</h1><p class="page-lead">Manage your profile, account, backend connection, and appearance.</p>${connection}<section class="panel" style="margin-bottom:20px"><p class="eyebrow">DESKTOP & DATA VAULT</p><h2>Keep your DevShow data</h2><p class="subtle" style="margin:12px 0">Download the Windows .exe to save locally, or export your server account data as JSON.</p><div class="hero-actions"><button class="btn primary small" data-action="nav" data-page="download">${icon('download','tiny-icon')} Windows app</button>${signedIn()?'<button class="btn secondary small" data-action="cloud-export">Export account data</button><button class="btn secondary small" data-action="change-password">Change password</button>':''}</div></section>` + demoSettingsPage().replace(/^.*?<div class="panel">/s,'<div class="panel">').replace(/<h3>Edit demo profile<\/h3>/,'<h3>Edit profile</h3>');
}
function profileForm() {
  if (isCloud() && !requireAccount()) return '<div></div>';
  const publicMine=state.mine.filter(p=>(p.visibility||'public')==='public');
  const options=`<div class="field"><label for="f-pin">Pinned public project</label><select name="pinnedProjectId" id="f-pin"><option value="">No pinned project</option>${publicMine.map(p=>`<option value="${safeText(p.id)}" ${state.user.pinnedProjectId===p.id?'selected':''}>${safeText(p.title)}</option>`).join('')}</select><small>Only public projects can be pinned to your public profile.</small></div>`;
  return demoProfileForm().replace('Edit your demo profile','Manage your public profile').replace('<div class="form-actions">',options+'<div class="form-actions">');
}
function notificationsModal() {
  if (!isCloud()) return demoNotificationsModal();
  return `<div class="modal-header"><h2>Notifications</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="modal-content"><div class="notification-list">${!signedIn()?'<p>Sign in to receive activity notifications.</p>':cloud.notifications.length?cloud.notifications.map(n=>`<div class="notification">${icon(n.kind==='like'?'heart':n.kind==='follow'?'users':'message')}<div><strong>${safeText(n.actor)} ${n.kind==='follow'?'followed you':n.kind==='like'?'liked your project':'commented on your project'}</strong><p>${safeText(n.created_at)}</p></div></div>`).join(''):'<p>No new notifications.</p>'}</div>${signedIn()?'<button class="btn secondary small" style="margin-top:16px" data-action="read-notifications">Mark as read</button>':''}</div>`;
}
function authModal() { return `<div class="modal-header"><h2>${signedIn()?'Your account':'Sign in or join DevShow'}</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="modal-content">${signedIn()?`<div class="panel"><h3>${safeText(state.user.name)}</h3><p>@${safeText(state.user.handle)}</p><p class="subtle">Your profile and projects are saved on the Node server.</p><button class="btn secondary" data-action="logout" style="margin-top:16px">Sign out</button></div>`:!online()?`<p class="notice">Connect a running Node.js server in Settings before creating an account.</p><button class="btn primary" data-action="server">Connect server</button>`:`<form id="auth-form" class="auth-form"><label class="field"><span>Action</span><select name="mode" id="auth-mode"><option value="login">Sign in</option><option value="register">Create account</option></select></label><div id="register-fields" hidden>${field('name','Display name','Your name','','text','')}${field('handle','Username','developer123','','text','minlength="3" maxlength="24"')}</div>${field('email','Email address or username','you@example.com','','text','required')}${field('password','Password','At least 10 characters','','password','required minlength="10"')}<p class="subtle">Credentials are verified by the Node server, not GitHub Pages. Session stays active for this browser tab.</p><div class="form-actions"><button class="btn primary" type="submit">Continue</button></div></form>`}</div>`; }
function passwordModal() { return `<div class="modal-header"><h2>Change account password</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="password-form"><p class="page-lead">Changing your password signs out all active sessions on this server.</p>${field('currentPassword','Current password','','','password','required')}${field('newPassword','New password (10+ characters)','','','password','required minlength="10" maxlength="128"')}<div class="form-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">Update password</button></div></form>`; }
function serverModal() { return `<div class="modal-header"><h2>Connect DevShow API</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="server-form"><p class="modal-summary">Paste the public HTTPS URL where you host the Node.js server. GitHub Pages cannot run Node.js by itself. Use <code>http://localhost:3000</code> for local testing.</p>${field('apiUrl','Node.js API base URL','https://devshow-api.example.com',apiBase(),'url','') }<div class="notice">Leave blank to return to the local demonstration. Do not paste any API password, secret, or private token.</div><div class="form-actions"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">Save & connect</button></div></form>`; }
function renderPage() { return ({ discover: homePage, explore: explorePage, bookmarks: () => collectionPage('bookmarks'), boards: boardsPage, studio: studioPage, download: downloadPage, following: () => collectionPage('following'), leaderboard: leaderboardPage, 'my-projects': () => collectionPage('my-projects'), profile: profilePage, settings: settingsPage })[state.page]?.() || homePage(); }
function demoRenderAside() { return `<div class="aside-card"><div class="aside-head"><h3>Community pulse</h3>${icon('fire')}</div>${seedProjects.slice(0,3).map((p) => `<div class="activity">${avatar(getCreator(p.creatorId))}<div class="activity-text"><b>${safeText(getCreator(p.creatorId).name)}</b> shared <button class="link" style="font-size:12px" data-action="open" data-id="${p.id}">${safeText(p.title)}</button><div class="activity-time">${p.daysAgo}d ago · Sample activity</div></div></div>`).join('')}</div><div class="aside-card"><div class="aside-head"><h3>Top creators</h3><button class="link" style="font-size:11px" data-action="nav" data-page="leaderboard">View all</button></div>${ranking().slice(0,4).map((c,i) => `<button class="leader" data-action="profile" data-id="${c.id}" style="width:100%;text-align:left;background:none;border:0;color:var(--text);padding:0"><span class="leader-rank">${i+1}</span>${avatar(c)}<span class="leader-info"><strong>${safeText(c.name)}</strong><small>@${safeText(c.handle)}</small></span><span class="leader-points">${fmt(c.score)}</span></button>`).join('')}</div><div class="aside-banner"><p class="eyebrow" style="margin:0 0 8px;color:#b4ffa6">✦ SHOW YOUR WORK</p><h3>Your next big idea starts here.</h3><p>Every project has a story. Tell yours.</p><button class="btn primary small" data-action="new">Start sharing ${icon('arrow','tiny-icon')}</button></div><p style="color:var(--soft);font-size:10px;padding:0 5px;line-height:1.7">DevShow v1.5 preview · Local-first prototype<br/>Sample community profiles and projects. <button class="link" style="font-size:10px" data-action="nav" data-page="settings">About demo mode</button></p>`; }
