function newProjectForm(project = null) { const edit = Boolean(project); const p = project || {}; return `<div class="modal-header"><div><p class="eyebrow" style="margin-bottom:5px">${edit ? 'REFINE YOUR SHOWCASE' : 'NEW SHOWCASE'}</p><h2>${edit ? 'Edit project' : 'Share your project'}</h2></div><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="${edit ? 'edit-form' : 'create-form'}" ${edit ? `data-id="${safeText(p.id)}"` : ''}><p class="modal-summary">${edit ? 'Keep your project details fresh.' : 'Show what you have been building.'} ${online()?'Changes are saved to your DevShow account.':'This is a local preview until a server is connected.'}</p><div class="form-grid">${field('title','Project name *','e.g. My Awesome App',p.title || '','text','required maxlength="70"')}<div class="field"><label for="f-category">Category *</label><select id="f-category" name="category" required>${categories.slice(1).map((c) => `<option value="${safeText(c.name)}" ${c.name === p.category ? 'selected' : ''}>${safeText(c.name)}</option>`).join('')}</select></div><div class="field span2">${field('tagline','One-line description *','What makes it special?',p.tagline || '','text','required maxlength="140"')}</div><div class="field span2"><label for="f-description">Full description *</label><textarea name="description" id="f-description" placeholder="Tell us what it does and why you built it..." minlength="20" maxlength="3000" required>${safeText(p.description || '')}</textarea></div><div class="field span2">${field('tags','Tags (comma-separated)','React, Open Source, UI',(p.tags || []).join(', '),'text','maxlength="180"')}</div><div class="field"><label for="f-visibility">Who can see this project?</label><select id="f-visibility" name="visibility">${[['public','Public · listed in Discover'],['unlisted','Unlisted · link access only'],['private','Private · only you']].map(([value,label])=>`<option value="${value}" ${(p.visibility||'public')===value?'selected':''}>${label}</option>`).join('')}</select><small>Enforced by the API when connected. Unlisted is not secret: anyone with its link can view it.</small></div>${field('repo','GitHub repository URL','https://github.com/owner/repo',p.repo || '','url')}${field('website','Live website URL','https://example.com',p.website || '','url')}<div class="field span2">${field('cover','Project cover image URL (optional)','https://example.com/screenshot.png',p.cover || '','url')}<small>Use an HTTPS image URL to show a custom project thumbnail. No file upload or hosting is included.</small></div></div>${edit ? '' : `<div class="notice"><b>Have a public GitHub repo?</b> Import title, language and tags automatically. <button class="link" data-action="import" type="button">Import from GitHub ${icon('arrow','tiny-icon')}</button></div>`}<div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn primary">${icon(edit ? 'check':'upload','tiny-icon')} ${edit ? 'Save changes' : online() ? 'Publish project' : 'Save locally'}</button></div></form>`; }
function boardForm() { return `<div class="modal-header"><h2>Create a collection</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="board-form"><p class="modal-summary">Organize your favorite projects into a personalized collection.</p>${field('name','Collection name *','e.g. Inspiring UI design','','text','required maxlength="50"')}${field('description','Description','A place for ideas I want to revisit','','text','maxlength="160"')}<div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn primary">Create collection</button></div></form>`; }
