function menuModal() { const pages = [['discover','compass','Discover'], ['explore','grid','Explore'], ['bookmarks','bookmark','Saved projects'], ['boards','layers','Collections'], ['following','users','Following'], ['leaderboard','trophy','Leaderboard'], ['studio','chart','Creator Studio'], ['my-projects','folder','My projects'], ['profile','user','My profile'], ['settings','settings','Settings']]; return `<div class="modal-header"><h2>Explore DevShow</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="modal-content"><p class="modal-summary">Everything you need, one tap away.</p><div class="mobile-menu-grid">${pages.map(([page,glyph,title])=>`<button class="mobile-menu-link" data-action="${page === 'profile' ? 'profile' : 'nav'}" ${page === 'profile' ? 'data-id="self"' : `data-page="${page}"`}>${icon(glyph)}<span>${title}</span>${icon('chevron','tiny-icon')}</button>`).join('')}</div></div>`; }
function shortcutsModal() { return `<div class="modal-header"><h2>Keyboard shortcuts</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="modal-content shortcuts-table"><div><span>Quick search</span><kbd>Ctrl/⌘ K</kbd></div><div><span>Share a project</span><kbd>N</kbd></div><div><span>Explore projects</span><kbd>G then E</kbd></div><div><span>Creator Studio</span><kbd>G then S</kbd></div><div><span>Close dialog</span><kbd>Esc</kbd></div></div>`; }
function importForm() { return `<div class="modal-header"><h2>Import a GitHub repository</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="import-form"><p class="modal-summary">Paste a <b>public</b> GitHub repository URL. DevShow will fetch public metadata and create a local showcase. No login token is used.</p>${field('repo','Repository URL *','https://github.com/owner/repo','','url','required')}<div class="notice">Only public repository metadata is fetched. GitHub API rate limits or network restrictions can prevent an import. Private repositories are not supported in this demo.</div><div class="form-actions"><button class="btn secondary" type="button" data-action="new">Back</button><button class="btn primary" id="import-button" type="submit">${icon('github','tiny-icon')} Import project</button></div></form>`; }
function demoProfileForm() { return `<div class="modal-header"><h2>Edit your demo profile</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><form class="modal-content" id="profile-form">${field('name','Display name', 'Your name', state.user.name,'text','required maxlength="40"')}${field('handle','Username','yourhandle',state.user.handle,'text','required pattern="[a-zA-Z0-9_-]{2,24}" title="2–24 letters, numbers, underscores or hyphens"')}${field('role','Role or headline','Full-stack developer',state.user.role,'text','maxlength="70"')}${field('location','Location (optional)','Alaska, USA',state.user.location||'','text','maxlength="80"')}${field('skills','Skills (comma-separated)','TypeScript, Luau, Rust',(state.user.skills||[]).join(', '),'text','maxlength="350"')}<div class="field"><label for="f-bio">Bio</label><textarea name="bio" id="f-bio" maxlength="300">${safeText(state.user.bio)}</textarea></div><div class="form-grid">${field('github','GitHub profile','https://github.com/yourname',state.user.github || "",'url')}${field('website','Portfolio website','https://yourportfolio.dev',state.user.website || "",'url')}</div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn primary" type="submit">Save profile</button></div></form>`; }
function projectDetail(p) {
  const author = getCreator(p.creatorId); const liked = state.liked.includes(p.id); const saved = state.saved.includes(p.id);
  const userComments = state.comments[p.id] || [];
  const repo = validUrl(p.repo); const website = validUrl(p.website);
  return `<div class="modal-header"><span class="subtle">Project showcase / ${safeText(p.category)} · ${safeText(p.visibility||'public')}</span><button class="iconbtn" aria-label="Close" data-action="close">${icon('close')}</button></div><div class="modal-content">${projectThumb(p)}<div class="detail-top"><div><p class="eyebrow">CREATED BY THE COMMUNITY</p><h2>${safeText(p.title)}</h2><p class="subtle" style="margin-top:6px">${safeText(p.tagline)}</p></div>${isMine(p) ? `<div class="detail-manage"><button class="btn secondary small" data-action="edit" data-id="${safeText(p.id)}">${icon('edit','tiny-icon')} Edit</button><button class="btn secondary small" data-action="delete" data-id="${safeText(p.id)}">${icon('trash','tiny-icon')} Delete</button></div>` : ''}</div><button class="author" data-action="profile" data-id="${p.creatorId}" style="margin:15px 0">${avatar(author,'medium')}<span><b style="display:block">${safeText(author.name)}</b><span class="author-info">@${safeText(author.handle)}</span></span>${icon('chevron','tiny-icon')}</button><p style="white-space:pre-wrap;overflow-wrap:anywhere">${safeText(p.description)}</p><div class="tags">${p.tags.map((tag) => `<span class="tag">${safeText(tag)}</span>`).join('')}</div><div class="detail-links">${repo ? `<a href="${safeText(repo)}" target="_blank" rel="noopener noreferrer" class="btn secondary small">${icon('github','tiny-icon')} Source code ${icon('external','tiny-icon')}</a>` : ''}${website ? `<a href="${safeText(website)}" target="_blank" rel="noopener noreferrer" class="btn secondary small">${icon('globe','tiny-icon')} Website ${icon('external','tiny-icon')}</a>` : ''}${online() && p.visibility!=='private' ? `<button class="btn secondary small" data-action="share" data-id="${safeText(p.id)}">${icon('link','tiny-icon')} ${p.visibility==='unlisted'?'Copy unlisted link':'Copy project link'}</button>` : isCloud() ? '<span class="subtle">Private · only you</span>' : '<span class="subtle">Local demo · not shared online</span>'}</div>${repo&&online()?`<section class="github-panel" id="github-${safeText(p.id)}"><span class="subtle">Loading public GitHub repository details…</span></section>`:''}<div class="detail-collect"><button class="btn secondary small" data-action="board-pick" data-id="${safeText(p.id)}">${icon('layers','tiny-icon')} Add to collection</button>${isMine(p) ? `<button class="btn secondary small" data-action="update" data-id="${safeText(p.id)}">${icon('plus','tiny-icon')} Post an update</button>` : ''}</div><div class="detail-stats"><button class="reaction ${liked ? 'active' : ''}" data-action="like" data-id="${p.id}">${icon('heart')} ${fmt(p.likes + Number(liked))} likes</button><button class="reaction bookmarked ${saved ? 'active' : ''}" data-action="save" data-id="${p.id}">${icon('bookmark')} ${saved ? 'Saved' : 'Save'}</button><span>${icon('eye','tiny-icon')} ${fmt(p.views)} views*</span><span>${icon('message','tiny-icon')} ${p.comments + userComments.length} comments*</span></div><p style="color:var(--soft);font-size:10px;margin-top:7px">${online()?'Community metrics saved by the Node.js API.':'Demo metrics stay in this browser.'}</p><div class="updates-section"><div class="section-head"><h3>Build log</h3><span class="subtle">${(state.updates[p.id] || []).length} updates</span></div>${(state.updates[p.id] || []).length ? state.updates[p.id].map((entry) => `<article class="update-entry"><div class="update-entry-meta"><span class="update-version">${safeText(entry.version || 'UPDATE')}</span><span>${safeText(entry.date || '')}</span></div><h4>${safeText(entry.title)}</h4><p>${safeText(entry.body)}</p></article>`).join('') : `<p class="subtle">${isMine(p) ? 'Share updates as you build and improve this project.' : 'No updates in this preview.'}</p>`}</div><h3 style="margin-top:25px">Discussion</h3>${userComments.length ? userComments.map((c) => `<div class="comment">${avatar(getCreator('self'))}<div class="comment-body"><strong>${safeText(c.name)}</strong><p>${safeText(c.text)}</p></div></div>`).join('') : `<p class="subtle" style="font-size:12px;margin-top:9px">${online()?'No comments yet. Be the first to contribute.':'Your comments are only saved in this browser.'}</p>`}<form id="comment-form" class="comment-form" data-id="${p.id}"><input name="comment" placeholder="Leave a thoughtful comment..." maxlength="500" required aria-label="Write comment"/><button class="btn primary" type="submit" aria-label="Send comment">${icon('send','tiny-icon')}</button></form></div>`;
}
function demoNotificationsModal() { return `<div class="modal-header"><h2>Notifications</h2><button class="iconbtn" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="modal-content"><div class="notice"><b>Preview only:</b> Live notifications and shared activity need the DevShow API.</div><div class="notification-list"><div class="notification">${icon('heart')}<div><strong>Welcome to DevShow</strong><p>Your developer community starts here. Publish your first project.</p></div></div><div class="notification">${icon('info')}<div><strong>You're using a local demo</strong><p>Data saves on this browser, not across devices.</p></div></div></div></div>`; }
function renderModal() { if (!modal) return ''; const content = modal.type === 'new' ? newProjectForm() : modal.type === 'edit' ? newProjectForm(getProject(modal.id)) : modal.type === 'create-board' ? boardForm() : modal.type === 'board-pick' ? boardPicker(getProject(modal.id)) : modal.type === 'update' ? updateForm(getProject(modal.id)) : modal.type === 'shortcuts' ? shortcutsModal() : modal.type === 'menu' ? menuModal() : modal.type === 'import' ? importForm() : modal.type === 'edit-profile' ? profileForm() : modal.type === 'notifications' ? notificationsModal() : modal.type === 'auth' ? authModal() : modal.type === 'server' ? serverModal() : modal.type === 'password' ? passwordModal() : modal.type === 'project' ? projectDetail(getProject(modal.id)) : ''; return `<div class="modal-backdrop" id="dialog-backdrop"><div class="modal ${modal.type === 'project' ? 'wide' : ''}" role="dialog" aria-modal="true" aria-label="${modal.type === 'project' ? 'Project details' : modal.type === 'new' ? 'Publish project' : modal.type === 'import' ? 'Import GitHub repository' : modal.type === 'edit-profile' ? 'Edit profile' : modal.type === 'edit' ? 'Edit project' : modal.type === 'create-board' ? 'Create collection' : modal.type === 'board-pick' ? 'Add to collection' : modal.type === 'update' ? 'Build update' : modal.type === 'shortcuts' ? 'Keyboard shortcuts' : modal.type === 'menu' ? 'Navigation' : 'Notifications'}">${content}</div></div>`; }
async function loadGithubPanel(id) {
  const p=getProject(id);
  const container=document.getElementById('github-'+id);
  if(!p || !container || !online() || !p.repo) return;
  try {
    const {repository:r}=await api(`/projects/${encodeURIComponent(id)}/github`);
    if(!container.isConnected) return;
    container.innerHTML=`<p class="eyebrow">OPEN-SOURCE COLLABORATION</p><h3>${icon('github','tiny-icon')} ${safeText(r.fullName)}</h3><p class="subtle">${safeText(r.description||'Public GitHub repository')}</p><div class="github-stats"><span>★ ${fmt(r.stars)} stars</span><span>⑂ ${fmt(r.forks)} forks</span><span>${safeText(r.language||'Other')}</span><span>${safeText(r.license||'No license specified')}</span></div><div class="github-links"><a href="${safeText(r.url)}" target="_blank" rel="noopener noreferrer">Source code ↗</a><a href="${safeText(r.pullRequestsUrl)}" target="_blank" rel="noopener noreferrer">Pull requests ↗</a>${r.issuesUrl?`<a href="${safeText(r.issuesUrl)}" target="_blank" rel="noopener noreferrer">Issues ↗</a>`:''}<a href="${safeText(r.releasesUrl)}" target="_blank" rel="noopener noreferrer">Releases ↗</a></div>${!r.license?'<p class="subtle">No open-source license detected: public source alone does not grant reuse permission.</p>':''}`;
  } catch(err) { if(container.isConnected)container.textContent='GitHub metadata unavailable: '+err.message; }
}
async function openLinkedProject(id) {
  if(!online()) { const local=getProject(id);if(local)openModal('project',id);return; }
  try {
    const details=await api(`/projects/${encodeURIComponent(id)}`);
    if(!cloud.projects.some(p=>p.id===id) && !state.mine.some(p=>p.id===id)) cloud.linked.push(details.project);
    if(details.creator&&!cloud.creators.some(c=>c.id===details.creator.id)) cloud.creators.push(details.creator);
    state.comments[id]=details.comments.map(c=>({name:c.name,text:c.text}));
    state.updates[id]=details.updates.map(u=>({title:u.title,body:u.body,version:u.version,date:String(u.date||'').slice(0,10)}));
    openModal('project',id);
  } catch(err) { toast('This project is private, unavailable, or has been deleted.',true); }
}
function render() { document.documentElement.dataset.theme = state.theme; $('#app').innerHTML = appShell(); document.body.style.overflow = modal ? 'hidden' : ''; if (modal) requestAnimationFrame(() => $('#dialog-backdrop .iconbtn')?.focus()); }
function refreshContent() { const el = $('#content-slot'); if (el) el.innerHTML = renderPage(); const aside = $('#aside-slot'); if (aside) aside.innerHTML = renderAside(); const bc = $('#breadcrumb'); if (bc) bc.textContent = titleForPage(); }
function openModal(type,id) { previousFocus = document.activeElement; modal = { type, id }; $('#modal-slot').innerHTML = renderModal(); document.body.style.overflow = 'hidden'; requestAnimationFrame(() => {$('#dialog-backdrop .iconbtn')?.focus();if(type==='project')loadGithubPanel(id);}); }
function closeModal() { modal = null; const slot = $('#modal-slot'); if (slot) slot.innerHTML = ''; document.body.style.overflow = ''; previousFocus?.focus?.(); previousFocus = null; }
function toast(message,isError = false) { const region = $('#toast-region'); if (!region) return; region.innerHTML = `<div class="toast ${isError ? 'error' : ''}">${icon(isError ? 'info' : 'check')} ${safeText(message)}</div>`; clearTimeout(toastTimer); toastTimer = setTimeout(() => { region.innerHTML = ''; }, 3500); }
function navigate(page, creator = 'self') { if (!['discover','explore','bookmarks','boards','studio','following','leaderboard','my-projects','profile','settings','download'].includes(page)) page = 'discover'; state.page = page; if (page === 'profile') profileId = creator; if (page !== 'boards') boardId = null; if (page !== 'explore' && page !== 'discover') state.search = ''; if (page === 'explore' || page === 'discover') state.category = 'All projects'; closeModal(); save(); render(); window.scrollTo({ top:0, behavior:'instant' }); if (location.hash !== `#${page}`) history.replaceState(null,'',`#${page}`); }
